1	import {jest} from '@jest/globals';
2	import net from 'node:net';
3	import {setLogger} from '../shared/logger.js';
4	import type {Express} from 'express';
5	import {createServer} from './createServer.js';
6	import type {ExtWebSocket} from './ws/connectionHandler.js';
7	import type {ChatSession} from '../types/session.js';
8	import type {SessionStore} from '../types/sessionStore.js';
9	import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';
10	import type {WsAuthenticator} from '../types/auth.js';
11	
12	// The defect this pins is an omission: both hooks are declared on HalServerOptions, and one was never forwarded.
13	
14	const settle = () => new Promise<void>(resolve => setTimeout(resolve, 0));
15	
16	const harness = (onConnect?: (session: ChatSession) => void) => {
17	  const sessionStore = {
18	    create: (sessionId: string, userId: string | number): ChatSession => ({sessionId, userId, entries: []}),
19	    delete: () => true,
20	  } as unknown as SessionStore;
21	
22	  const hal = createServer({
23	    app: (() => undefined) as unknown as Express,
24	    wsAuth: jest.fn() as unknown as WsAuthenticator,
25	    sessionStore,
26	    orchestrator: {} as ChatOrchestrator,
27	    onConnect,
28	  });
29	
30	  const ws = {
31	    userId: 'u1',
32	    isAlive: true,
33	    send: () => undefined,
34	    on: () => undefined,
35	    // The handler pauses the socket across an awaited create and resumes once its listeners are attached.
36	    pause: () => undefined,
37	    resume: () => undefined,
38	    close: () => undefined,
39	  } as unknown as ExtWebSocket;
40	
41	  return {hal, ws};
42	};
43	
44	describe('createServer hook wiring', () => {
45	  it('forwards onConnect to the connection handler', async () => {
46	    const seen: ChatSession[] = [];
47	    const {hal, ws} = harness(session => void seen.push(session));
48	
49	    hal.wss.emit('connection', ws);
50	    await settle();
51	    hal.wss.emit('close');
52	
53	    expect(seen.length).toBe(1);
54	  });
55	
56	  it('accepts a server configured without either hook', async () => {
57	    const {hal, ws} = harness();
58	
59	    hal.wss.emit('connection', ws);
60	    await settle();
61	    hal.wss.emit('close');
62	
63	    expect(hal.wss.listenerCount('connection')).toBe(1);
64	  });
65	});
66	
67	// An EventEmitter with no `error` listener throws, so a socket error on a running server ended the process.
68	describe('a server error after start', () => {
69	  const engineLines: string[] = [];
70	
71	  beforeEach(() => {
72	    engineLines.length = 0;
73	    const collect = (_category: string, message: string) => void engineLines.push(message);
74	    setLogger({debug: collect, info: collect, warn: collect, error: collect});
75	  });
76	
77	  afterEach(() => {
78	    setLogger();
79	  });
80	
81	  const started = async () => {
82	    const {hal} = harness();
83	    await hal.start(0);
84	    return hal;
85	  };
86	
87	  // A stopped engine and a port something else holds, so the next start is refused by the OS.
88	  const refusedStart = async () => {
89	    const hal = await started();
90	    await hal.stop();
91	    const blocker = net.createServer();
92	    await new Promise<void>(resolve => blocker.listen(0, resolve));
93	    const taken = (blocker.address() as net.AddressInfo).port;
94	    const release = () => new Promise<void>(resolve => blocker.close(() => resolve()));
95	    return {hal, taken, release};
96	  };
97	
98	  it('is reported rather than ending the process', async () => {
99	    const hal = await started();
100	
101	    hal.server.emit('error', new Error('late failure'));
102	    await hal.stop();
103	
104	    expect(engineLines).toContain('server error after start');
105	  });
106	
107	  it('leaves exactly one listener behind, however many times the server is restarted', async () => {
108	    const hal = await started();
109	    await hal.stop();
110	    await hal.start(0);
111	
112	    const count = hal.server.listenerCount('error');
113	    await hal.stop();
114	
115	    expect(count).toBe(1);
